import type { EnrichedImpactFinding } from './api-client';

export const impactSeverities = ['critical', 'high', 'medium', 'low', 'informational'];

export function deriveImpactView(findings: EnrichedImpactFinding[]) {
  const rank: Record<string, number> = { informational: 0, low: 1, medium: 2, high: 3, critical: 4 };
  const severity = impactSeverities.map((name) => ({ name, count: findings.filter((item) => item.severity === name).length }));
  const days = new Map<string, Record<string, number>>();
  findings.forEach((item) => { const day = item.detectedAt.slice(0, 10); const row = days.get(day) || { critical: 0, high: 0, medium: 0, low: 0, informational: 0 }; row[item.severity] = (row[item.severity] || 0) + 1; days.set(day, row); });
  const apiIds = [...new Set(findings.map((item) => item.dependentApiId))];
  const apiRisk = apiIds.map((id) => { const rows = findings.filter((item) => item.dependentApiId === id); const highestSeverity = rows.reduce((current, item) => (rank[item.severity] ?? -1) > (rank[current] ?? -1) ? item.severity : current, 'informational'); return { apiId: id, name: rows[0]?.dependentApiName || 'Unknown API', findings: rows.length, upstreamApis: new Set(rows.map((item) => item.changedApiId)).size, relationships: new Set(rows.flatMap((item) => item.dependencyId ? [item.dependencyId] : [])).size, affectedEndpoints: new Set(rows.flatMap((item) => item.affectedEndpointId ? [item.affectedEndpointId] : [])).size, highestSeverity }; });
  const categorySeverity = [...new Set(findings.map((item) => item.changeType))].map((category) => ({ category, values: Object.fromEntries(impactSeverities.map((key) => [key, findings.filter((item) => item.changeType === category && item.severity === key).length])) }));
  const depth = [1, 2, 3, 4].map((level) => { const rows = findings.filter((item) => level === 4 ? item.propagationDepth >= 4 : item.propagationDepth === level); return { depth: level, label: level === 1 ? 'Direct' : level === 4 ? 'Depth 4+' : `Depth ${level}`, uniqueApis: new Set(rows.map((item) => item.dependentApiId)).size, paths: rows.length }; });
  const matrix = [...new Set(findings.map((item) => `${item.changedApiId}:${item.dependentApiId}`))].map((key) => { const [upstreamApiId, dependentApiId] = key.split(':'); const rows = findings.filter((item) => item.changedApiId === upstreamApiId && item.dependentApiId === dependentApiId); const highestSeverity = rows.reduce((current, item) => (rank[item.severity] ?? -1) > (rank[current] ?? -1) ? item.severity : current, 'informational'); return { upstreamApiId: upstreamApiId!, upstreamApiName: rows[0]?.changedApiName || 'Unknown API', dependentApiId: dependentApiId!, dependentApiName: rows[0]?.dependentApiName || 'Unknown API', count: rows.length, highestSeverity, findings: rows }; });
  return { summary: { impactedApis: apiIds.length, directApis: new Set(findings.filter((item) => item.impact === 'direct').map((item) => item.dependentApiId)).size, transitiveApis: new Set(findings.filter((item) => item.impact === 'transitive').map((item) => item.dependentApiId)).size, highRiskFindings: findings.filter((item) => item.severity === 'critical' || item.severity === 'high').length, affectedEndpoints: new Set(findings.flatMap((item) => item.affectedEndpointId ? [item.affectedEndpointId] : [])).size, openFindings: findings.filter((item) => item.status === 'open' || item.status === 'under_review').length }, severity, timeSeries: [...days.entries()].sort(([a], [b]) => a.localeCompare(b)).map(([date, values]) => ({ date, critical: values.critical || 0, high: values.high || 0, medium: values.medium || 0, low: values.low || 0, informational: values.informational || 0 })), apiRisk, categorySeverity, depth, matrix };
}
