'use client';

import { useEffect, useMemo, useState } from 'react';
import { AlertTriangle, GitCompare, Network, RotateCcw, ShieldAlert, Waypoints } from 'lucide-react';
import { apiClient, type ImpactAnalytics } from '@/lib/api-client';
import { CategorySeverity, DirectTransitiveChart, ImpactOverTime, ImpactPropagationGraph, PropagationDepth, ResolutionTimeline, RiskBubbleChart, RiskMatrix, RiskTreemap, SeverityDonut } from '@/components/impact-visualizations';
import { deriveImpactView } from '@/lib/impact-analytics';

const severities = ['critical', 'high', 'medium', 'low', 'informational'];

export function ChangeIntelligence({ projectId }: { projectId: string }) {
  const [data, setData] = useState<ImpactAnalytics | null>(null); const [loading, setLoading] = useState(true); const [error, setError] = useState('');
  const [severity, setSeverity] = useState('all'); const [impact, setImpact] = useState('all'); const [apiId, setApiId] = useState('all'); const [range, setRange] = useState('90'); const [from, setFrom] = useState(''); const [to, setTo] = useState('');
  useEffect(() => { let mounted = true; void apiClient.changes.analytics(projectId).then((result) => { if (!mounted) return; if (result.success && result.data) setData(result.data); else setError(result.error?.message || 'Could not load change impact analytics.'); setLoading(false); }); return () => { mounted = false; }; }, [projectId]);
  const filtered = useMemo(() => { if (!data) return []; const now = Date.now(); return data.findings.filter((finding) => { const time = new Date(finding.detectedAt).getTime(); const rangeMatch = range === 'custom' ? (!from || time >= new Date(from).getTime()) && (!to || time <= new Date(`${to}T23:59:59`).getTime()) : range === 'all' || time >= now - Number(range) * 86_400_000; return rangeMatch && (severity === 'all' || finding.severity === severity) && (impact === 'all' || finding.impact === impact) && (apiId === 'all' || finding.changedApiId === apiId || finding.dependentApiId === apiId); }); }, [data, severity, impact, apiId, range, from, to]);
  const view = useMemo(() => data ? deriveImpactView(filtered) : null, [data, filtered]);
  const reset = () => { setSeverity('all'); setImpact('all'); setApiId('all'); setRange('90'); setFrom(''); setTo(''); };
  if (loading) return <div className="data-state impact-loading" role="status">Loading impact intelligence...</div>;
  if (error) return <div className="data-alert" role="alert">{error}</div>;
  if (!data || !view) return null;
  return <div className="workspace-page impact-workspace"><div className="impact-heading"><div><p className="page-kicker">Change intelligence / impact analysis</p><h2>Dependency risk workspace</h2><p>Trace persisted contract changes through real project dependencies and review the evidence behind every finding.</p></div><Waypoints size={22}/></div><section className="impact-filterbar" aria-label="Impact analysis filters"><label>API<select value={apiId} onChange={(event) => setApiId(event.target.value)}><option value="all">All APIs</option>{data.apis.map((api) => <option key={api.id} value={api.id}>{api.name}</option>)}</select></label><label>Severity<select value={severity} onChange={(event) => setSeverity(event.target.value)}><option value="all">All severities</option>{severities.map((item) => <option key={item} value={item}>{item.replaceAll('_', ' ')}</option>)}</select></label><label>Impact type<select value={impact} onChange={(event) => setImpact(event.target.value)}><option value="all">All impacts</option><option value="direct">Direct</option><option value="transitive">Transitive potential</option><option value="no_demonstrated_impact">No demonstrated impact</option></select></label><label>Date range<select value={range} onChange={(event) => setRange(event.target.value)}><option value="7">Last 7 days</option><option value="30">Last 30 days</option><option value="90">Last 90 days</option><option value="all">All time</option><option value="custom">Custom</option></select></label>{range === 'custom' && <><label>From<input type="date" value={from} onChange={(event) => setFrom(event.target.value)}/></label><label>To<input type="date" value={to} onChange={(event) => setTo(event.target.value)}/></label></>}<button onClick={reset}><RotateCcw size={14}/>Reset filters</button></section><section className="impact-section"><div className="impact-section-heading"><div><span>A</span><div><h3>Impact overview</h3><p>Current exposure, severity, and risk direction.</p></div></div><small>{filtered.length} filtered findings</small></div><div className="impact-summary-grid"><Metric icon={<Network/>} label="Impacted APIs" value={view.summary.impactedApis}/><Metric icon={<GitCompare/>} label="Directly impacted" value={view.summary.directApis}/><Metric icon={<Waypoints/>} label="Transitively impacted" value={view.summary.transitiveApis}/><Metric icon={<AlertTriangle/>} label="Critical / high risk" value={view.summary.highRiskFindings}/><Metric icon={<ShieldAlert/>} label="Affected endpoints" value={view.summary.affectedEndpoints}/><Metric icon={<AlertTriangle/>} label="Open findings" value={view.summary.openFindings}/></div><div className="impact-two-column"><SeverityDonut items={view.severity} active={severity} onSelect={setSeverity}/><ImpactOverTime rows={view.timeSeries}/></div></section><section className="impact-section"><SectionHeading code="B" title="Dependency propagation" subtitle="How contract risk moves through the ecosystem."/><ImpactPropagationGraph data={data} findings={filtered} onSelectApi={setApiId}/><div className="impact-two-column"><DirectTransitiveChart findings={filtered} onSelect={setApiId}/><PropagationDepth rows={view.depth}/></div></section><section className="impact-section"><SectionHeading code="C" title="Risk concentration" subtitle="Where dependency exposure accumulates across APIs."/><div className="impact-two-column"><RiskBubbleChart rows={view.apiRisk} onSelect={setApiId}/><RiskTreemap rows={view.apiRisk} onSelect={setApiId}/></div><RiskMatrix cells={view.matrix} onSelect={setApiId}/></section><section className="impact-section"><SectionHeading code="D" title="Change analysis" subtitle="Which contract changes create risk, and how findings progress."/><CategorySeverity rows={view.categorySeverity} activeSeverity={severity} onSeverity={setSeverity}/><ResolutionTimeline findings={filtered} history={data.statusHistory.filter((event) => filtered.some((finding) => finding.id === event.findingId))}/></section></div>;
}

function Metric({ icon, label, value }: { icon: React.ReactNode; label: string; value: number }) { return <article><span>{icon}</span><b>{value}</b><small>{label}</small></article>; }
function SectionHeading({ code, title, subtitle }: { code: string; title: string; subtitle: string }) { return <div className="impact-section-heading"><div><span>{code}</span><div><h3>{title}</h3><p>{subtitle}</p></div></div></div>; }
